// 独立师承段的有限 typed 账；拒重名、跨表重号、非法存在位，旧 Family visitor 不变。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "family_apprenticeship.hpp"
#include "family_projection.hpp"
#include "family_source_projection.hpp"
#include "succession_personal_assets.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <set>
namespace hanmo::resident {namespace {
using V=BoundaryValue;using P=ApprenticeshipProposal;using R=ApprenticeshipReply;using E=ApprenticeshipExit;using B=ApprenticeshipCommitBinding;
// 新建原生记录允许空字段序，冷记录必须完整且唯一，不能隐藏第二份决定。
bool order(const FieldOrder& value,const std::set<StableId>& keys){return value.empty()||(value.size()==keys.size()&&std::set<StableId>(value.begin(),value.end())==keys);}
bool id(const StableId& text){return !text.empty()&&text.size()<=256;}
Status shape(const P& p){if(p.kind!="family_apprenticeship_proposed"||!order(p.field_order,{"kind","source"}))return common_failure("InvalidApprenticeshipProposal");return validate_apprenticeship_source_shape(p.source);}
Status shape(const R& r){std::set<StableId> keys{"kind","proposal_id","actor_id","decision","tick","revision"};if(r.confirmation)keys.insert("confirmation");if(r.kind!="family_apprenticeship_replied"||!id(r.proposal_id)||!id(r.actor_id)||(r.decision!="accepted"&&r.decision!="refused"&&r.decision!="withdrawn")||bool(r.confirmation)!=(r.decision=="accepted")||r.tick<0||r.tick>2147483647||r.revision<0||!order(r.field_order,keys))return common_failure("InvalidApprenticeshipReply");return r.confirmation?validate_apprenticeship_source_shape(*r.confirmation):common_success();}
Status shape(const E& e){return e.kind=="family_apprenticeship_exited"&&id(e.bond_id)&&id(e.actor_id)&&e.tick>=0&&e.tick<=2147483647&&e.revision>=0&&order(e.field_order,{"kind","bond_id","actor_id","tick","revision"})?common_success():common_failure("InvalidApprenticeshipExit");}
Status shape(const B& b){return id(b.result_id)&&id(b.actor_id)&&(b.kind=="family_apprenticeship_receive"||b.kind=="family_apprenticeship_reply"||b.kind=="family_apprenticeship_exit")&&b.request_seq>0&&b.revision>0&&order(b.field_order,{"result_id","actor_id","kind","request_seq","revision"})?common_success():common_failure("InvalidApprenticeshipCommitBinding");}
ApprenticeshipStatementSource source(const V& v){auto read=decode_apprenticeship_statement_source(v);if(!read.ok)boundary::fail(read.error.original.code,"apprenticeship/source");return std::move(read.value);}
P proposal(const V& v){using namespace boundary;fields(v,{"kind","source"},{},"apprenticeship/proposal");P out;out.kind=get_string(v,"kind","");out.source=source(field(v,"source",""));out.field_order=boundary::order(v);return out;}
R reply(const V& v){using namespace boundary;fields(v,{"kind","proposal_id","actor_id","decision","tick","revision"},{"confirmation"},"apprenticeship/reply");R out;out.kind=get_string(v,"kind","");out.proposal_id=get_string(v,"proposal_id","");out.actor_id=get_string(v,"actor_id","");out.decision=get_string(v,"decision","");out.tick=get_int(v,"tick","");out.revision=get_int(v,"revision","");if(const auto* s=v.find("confirmation"))out.confirmation=source(*s);out.field_order=boundary::order(v);return out;}
E exit_record(const V& v){using namespace boundary;fields(v,{"kind","bond_id","actor_id","tick","revision"},{},"apprenticeship/exit");E out;out.kind=get_string(v,"kind","");out.bond_id=get_string(v,"bond_id","");out.actor_id=get_string(v,"actor_id","");out.tick=get_int(v,"tick","");out.revision=get_int(v,"revision","");out.field_order=boundary::order(v);return out;}
B binding(const V& v){using namespace boundary;fields(v,{"result_id","actor_id","kind","request_seq","revision"},{},"apprenticeship/commit");B out;out.result_id=get_string(v,"result_id","");out.actor_id=get_string(v,"actor_id","");out.kind=get_string(v,"kind","");out.request_seq=get_int(v,"request_seq","");out.revision=get_int(v,"revision","");out.field_order=boundary::order(v);return out;}
Status visit(CodecVisitor& v,P& p){v.field("kind",p.kind);v.object("source",[&](CodecVisitor& nested){return visit_apprenticeship_statement_source(nested,p.source);});common_checkpoint::strings(v,"field_order",p.field_order);if(!v.status().ok)return v.status();auto valid=shape(p);return valid.ok?v.status():v.reject(valid.error.original.code);}
Status visit(CodecVisitor& v,R& r){v.field("kind",r.kind);v.field("proposal_id",r.proposal_id);v.field("actor_id",r.actor_id);v.field("decision",r.decision);v.field("tick",r.tick);v.field("revision",r.revision);v.optional("confirmation",r.confirmation,[](CodecVisitor& nested,ApprenticeshipStatementSource& s){return visit_apprenticeship_statement_source(nested,s);});common_checkpoint::strings(v,"field_order",r.field_order);if(!v.status().ok)return v.status();auto valid=shape(r);return valid.ok?v.status():v.reject(valid.error.original.code);}
Status visit(CodecVisitor& v,E& e){v.field("kind",e.kind);v.field("bond_id",e.bond_id);v.field("actor_id",e.actor_id);v.field("tick",e.tick);v.field("revision",e.revision);common_checkpoint::strings(v,"field_order",e.field_order);if(!v.status().ok)return v.status();auto valid=shape(e);return valid.ok?v.status():v.reject(valid.error.original.code);}
Status visit(CodecVisitor& v,B& b){v.field("result_id",b.result_id);v.field("actor_id",b.actor_id);v.field("kind",b.kind);v.field("request_seq",b.request_seq);v.field("revision",b.revision);common_checkpoint::strings(v,"field_order",b.field_order);if(!v.status().ok)return v.status();auto valid=shape(b);return valid.ok?v.status():v.reject(valid.error.original.code);}
// 分配号语义由完整 Common 事实门核；结构层先拒所有重复键和跨表重用。
template<class T,class Read>void decode_table(const V& v,OrderedTable<T>& table,Read read){const auto& rows=boundary::object(v,"apprenticeship/table");if(rows.size()>65536)boundary::fail("ApprenticeshipFactLimit","");for(const auto& row:rows){auto value=read(row.second);auto valid=shape(value);if(!valid.ok)boundary::fail(valid.error.original.code,row.first);if(!id(row.first)||!table.insert(row.first,std::move(value)))boundary::fail("InvalidApprenticeshipFactId",row.first);}}
}
Status validate_family_apprenticeship_shape(const FamilyApprenticeshipState& state){
    if(!order(state.field_order,{"proposals","replies","exits","commits"}))return common_failure("BoundaryFieldOrderMismatch");
    if(state.proposals.size()+state.replies.size()+state.exits.size()>65536)return common_failure("ApprenticeshipFactLimit");std::set<StableId> seen;
    auto table=[&](const auto& records)->Status{for(const auto& row:records.rows()){if(!id(row.first)||!seen.insert(row.first).second)return common_failure("InvalidApprenticeshipFactId",row.first);auto valid=shape(row.second);if(!valid.ok)return valid;}return common_success();};
    auto valid=table(state.proposals);if(!valid.ok)return valid;valid=table(state.replies);if(!valid.ok)return valid;valid=table(state.exits);if(!valid.ok)return valid;for(const auto& row:state.commits.rows()){if(!seen.count(row.first))return common_failure("ApprenticeshipCommitSourceRequired",row.first);valid=shape(row.second);if(!valid.ok)return valid;}return common_success();
}
Outcome<FamilyApprenticeshipState> decode_family_apprenticeship(const V& input){try{
    auto unique=validate_succession_json_unique(input);if(!unique.ok)return {false,{},unique.error};using namespace boundary;fields(input,{"proposals","replies","exits","commits"},{},"family_apprenticeship");FamilyApprenticeshipState state;decode_table(field(input,"proposals",""),state.proposals,proposal);decode_table(field(input,"replies",""),state.replies,reply);decode_table(field(input,"exits",""),state.exits,exit_record);decode_table(field(input,"commits",""),state.commits,binding);state.field_order=boundary::order(input);auto valid=validate_family_apprenticeship_shape(state);return valid.ok?Outcome<FamilyApprenticeshipState>{true,std::move(state),{}}:Outcome<FamilyApprenticeshipState>{false,{},valid.error};
}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_apprenticeship_proposal_fields(ProjectionWriter& w,const ApprenticeshipProposal& p){w.field("kind",p.kind);w.object("source",[&](auto& x){return emit_apprenticeship_statement_source_fields(x,p.source);});return w.order_fields(p.field_order);}
Status emit_apprenticeship_reply_fields(ProjectionWriter& w,const ApprenticeshipReply& r){w.field("kind",r.kind);w.field("proposal_id",r.proposal_id);w.field("actor_id",r.actor_id);w.field("decision",r.decision);w.field("tick",r.tick);w.field("revision",r.revision);if(r.confirmation)w.object("confirmation",[&](auto& x){return emit_apprenticeship_statement_source_fields(x,*r.confirmation);});return w.order_fields(r.field_order);}
Status emit_apprenticeship_exit_fields(ProjectionWriter& w,const ApprenticeshipExit& e){w.field("kind",e.kind);w.field("bond_id",e.bond_id);w.field("actor_id",e.actor_id);w.field("tick",e.tick);w.field("revision",e.revision);return w.order_fields(e.field_order);}
Status emit_apprenticeship_commit_fields(ProjectionWriter& w,const ApprenticeshipCommitBinding& b){w.field("result_id",b.result_id);w.field("actor_id",b.actor_id);w.field("kind",b.kind);w.field("request_seq",b.request_seq);w.field("revision",b.revision);return w.order_fields(b.field_order);}
Status emit_family_apprenticeship_fields(ProjectionWriter& w,const FamilyApprenticeshipState& state){auto valid=validate_family_apprenticeship_shape(state);if(!valid.ok)return w.reject(valid.error.original.code,"family_apprenticeship");w.object("proposals",[&](auto& table){for(const auto& row:state.proposals.rows())table.object(row.first,[&](auto& record){return emit_apprenticeship_proposal_fields(record,row.second);});return table.status();});w.object("replies",[&](auto& table){for(const auto& row:state.replies.rows())table.object(row.first,[&](auto& record){return emit_apprenticeship_reply_fields(record,row.second);});return table.status();});w.object("exits",[&](auto& table){for(const auto& row:state.exits.rows())table.object(row.first,[&](auto& record){return emit_apprenticeship_exit_fields(record,row.second);});return table.status();});w.object("commits",[&](auto& table){for(const auto& row:state.commits.rows())table.object(row.first,[&](auto& record){return emit_apprenticeship_commit_fields(record,row.second);});return table.status();});return w.order_fields(state.field_order);}
BoundaryValue encode_family_apprenticeship(const FamilyApprenticeshipState& state){return family_projection::encode([&](auto& w){return emit_family_apprenticeship_fields(w,state);});}
Status visit_family_apprenticeship_checkpoint(CodecVisitor& v,FamilyApprenticeshipState& state){common_checkpoint::table(v,"proposals",state.proposals,[](CodecVisitor& nested,P& p){return visit(nested,p);});common_checkpoint::table(v,"replies",state.replies,[](CodecVisitor& nested,R& r){return visit(nested,r);});common_checkpoint::table(v,"exits",state.exits,[](CodecVisitor& nested,E& e){return visit(nested,e);});common_checkpoint::table(v,"commits",state.commits,[](CodecVisitor& nested,B& b){return visit(nested,b);});common_checkpoint::strings(v,"field_order",state.field_order);if(!v.status().ok)return v.status();auto valid=validate_family_apprenticeship_shape(state);return valid.ok?v.status():v.reject(valid.error.original.code);}
}
